package main

import "fmt"

type Point struct{ X, Y int }

// Returned by value: stays on the caller's stack, no allocation.
func onStack() Point {
	return Point{X: 1, Y: 2}
}

// Returns a pointer: value must outlive the frame, so it escapes.
func onHeap() *Point {
	p := Point{X: 3, Y: 4}
	return &p // escapes to heap
}

func main() {
	fmt.Println(onStack(), *onHeap())
	// Output: {1 2} {3 4}
}

// $ go build -gcflags='-m' main.go
// ./main.go:13:2: moved to heap: p

package main

import "fmt"

// Bad: append grows and copies the backing array many times.
func squaresSlow(n int) []int {
	var out []int
	for i := 0; i < n; i++ {
		out = append(out, i*i)
	}
	return out
}

// Good: pre-size once, so the whole loop is a single allocation.
func squaresFast(n int) []int {
	out := make([]int, 0, n)
	for i := 0; i < n; i++ {
		out = append(out, i*i)
	}
	return out
}

func main() {
	fmt.Println(squaresFast(4))
	// Output: [0 1 4 9]
}

package main

import (
	"bytes"
	"fmt"
	"sync"
)

// New runs only when the pool is empty.
var bufPool = sync.Pool{New: func() any { return new(bytes.Buffer) }}

func greet(name string) string {
	b := bufPool.Get().(*bytes.Buffer)
	defer bufPool.Put(b) // return for the next caller
	b.Reset()            // critical: clear stale state
	b.WriteString("hello, ")
	b.WriteString(name)
	return b.String() // copy out before Put recycles the buffer
}

func main() {
	fmt.Println(greet("ada"))
	fmt.Println(greet("go"))
	// Output:
	// hello, ada
	// hello, go
}

package main

import (
	"fmt"
	"strings"
)

func join(words []string) string {
	n := len(words) // room for separators
	for _, w := range words {
		n += len(w)
	}
	var b strings.Builder
	b.Grow(n) // pre-size: one allocation for the whole result
	for i, w := range words {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(w)
	}
	return b.String() // no extra copy of the final bytes
}

func main() {
	fmt.Println(join([]string{"a", "b", "c"}))
	// Output: a,b,c
}

