package main

import (
	"fmt"
	"runtime/debug"
)

func main() {
	// Equivalent to GOGC=200: let the heap grow to 200% of live
	// data before collecting, trading memory for fewer GC cycles.
	prev := debug.SetGCPercent(200)

	// Soft ceiling (Go 1.19+): GC works harder near 512 MiB to
	// avoid OOM in a constrained container.
	debug.SetMemoryLimit(512 << 20)

	fmt.Println("previous GOGC:", prev)
	// Output: previous GOGC: 100
}

// Or set at launch: GOGC=200 GOMEMLIMIT=512MiB ./server

