func join(words []string) string {
	var b strings.Builder // writes into one growable buffer
	n := 0
	for _, w := range words {
		n += len(w) + 1
	}
	b.Grow(n) // pre-size: one allocation for the whole result
	for i, w := range words {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(w)
	}
	return b.String() // no extra copy of the final bytes
}

func main() {
	fmt.Println(join([]string{"a", "b", "c"}))
