package solution

import (
	"strconv"
	"strings"
)

func JoinInts(nums []int, sep string) string {
	if len(nums) == 0 {
		return ""
	}
	var b strings.Builder
	// Rough pre-size: ~12 chars per int (handles negatives & int64) plus separators.
	// Grow once so the Builder's backing buffer is a single allocation.
	b.Grow(len(nums)*12 + len(sep)*(len(nums)-1))

	var scratch [20]byte // stack-allocated; never escapes
	for i, n := range nums {
		if i > 0 {
			b.WriteString(sep)
		}
		// AppendInt formats n into scratch[:0] without allocating a string.
		b.Write(strconv.AppendInt(scratch[:0], int64(n), 10))
	}
	return b.String()
}

