func (l *Logger) Debugf(format string, args ...any) {
	// Cheap check first: if Debug is off, return before any formatting
	// or interface boxing of args occurs.
	if l.level > DebugLevel {
		return
	}
	l.write(fmt.Sprintf(format, args...))
}

// Hot-path callers can guard too, so args aren't even evaluated/boxed:
for _, r := range requests {
	if log.Enabled(DebugLevel) {
		log.Debugf("handling %d", r.ID)
	}
}

func Sum(line []byte) int {
	total, cur := 0, 0
	for _, c := range line {
		if c == ',' {
			total += cur // commit the finished number
			cur = 0
			continue
		}
		cur = cur*10 + int(c-'0') // shift in the next digit
	}
	return total + cur // commit the last number
}

// AppendCSV appends fields joined by commas plus a newline to dst,
// returning the extended slice. Reusing dst makes calls allocation-free.
func AppendCSV(dst []byte, fields []string) []byte {
	for i, f := range fields {
		if i > 0 {
			dst = append(dst, ',')
		}
		dst = append(dst, f...) // appends string bytes; no []byte(f) conversion
	}
	return append(dst, '\n')
}

// Benchmark: reuse one buffer so append never reallocates in steady state.
func BenchmarkAppendCSV(b *testing.B) {
	fields := []string{"alpha", "beta", "gamma", "delta"}
	buf := make([]byte, 0, 64)
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		buf = AppendCSV(buf[:0], fields) // reset length, keep capacity
	}
	_ = buf
}
